# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HÜCRESEL YAPI VE ORGANİZASYON BASAMAKLARI</text>\n  <rect x="25" y="42" width="320" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">PROKARYOT VE ÖKARYOT HÜCRE</text>\n  <rect x="38" y="76" width="294" height="72" rx="6" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="48" y="95" font-size="12" font-weight="bold" fill="#1d4ed8">• Prokaryot Hücre (Bakteri ve Arkeler):</text>\n  <text x="55" y="113" font-size="11" fill="#1e3a8a">Zarla çevrili çekirdek ve zarlı organel YOKTUR.</text>\n  <text x="55" y="130" font-size="11" fill="#1e3a8a">DNA sitoplazmada dağılmıştır; ribozom bulunur.</text>\n  <rect x="38" y="156" width="294" height="76" rx="6" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="48" y="175" font-size="12" font-weight="bold" fill="#1d4ed8">• Ökaryot Hücre (Protista, Bitki, Mantar, Hayvan):</text>\n  <text x="55" y="193" font-size="11" fill="#1e3a8a">Zarla çevrili çekirdek ve zarlı organeller VARDIR.</text>\n  <text x="55" y="210" font-size="11" fill="#1e3a8a">Tek hücreli (amip, öglena) veya çok hücreli olabilir.</text>\n  <rect x="360" y="42" width="315" height="202" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">ORGANİZASYON BASAMAKLARI</text>\n  <text x="517" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Atom → Molekül → Organel → Hücre</text>\n  <text x="517" y="110" text-anchor="middle" font-size="11" fill="#166534">(Tek hücreli canlıların organizasyonu Hücre\'de biter)</text>\n  <line x1="400" y1="122" x2="635" y2="122" stroke="#86efac" stroke-width="2"/>\n  <text x="517" y="145" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Hücre → Doku → Organ → Sistem → Organizma</text>\n  <text x="517" y="165" text-anchor="middle" font-size="11" fill="#166534">(Çok hücreli canlılarda iş bölümü ve hiyerarşi)</text>\n  <rect x="378" y="180" width="278" height="50" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="517" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Tüm Hücrelerde Ortak Yapılar:</text>\n  <text x="517" y="217" text-anchor="middle" font-size="11" fill="#166534">Hücre zarı, Sitoplazma, Ribozom, Nükleik asitler (DNA, RNA)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BESLENME, ENERJİ ÜRETİMİ VE METABOLİZMA (ANABOLİZMA - KATABOLİZMA)</text>\n  <rect x="25" y="42" width="315" height="202" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">BESLENME VE ENERJİ (ATP)</text>\n  <text x="38" y="92" font-size="12" font-weight="bold" fill="#78350f">• Üretici (Ototrof) Canlılar:</text>\n  <text x="48" y="110" font-size="11" fill="#92400e">İnorganik maddelerden organik besin üretir (Bitkiler, algler).</text>\n  <text x="38" y="135" font-size="12" font-weight="bold" fill="#78350f">• Tüketici (Heterotrof) Canlılar:</text>\n  <text x="48" y="153" font-size="11" fill="#92400e">Besinlerini dışarıdan hazır alır (Hayvanlar, mantarlar).</text>\n  <text x="38" y="180" font-size="12" font-weight="bold" fill="#78350f">• Hücresel Solunum ve Fermantasyon:</text>\n  <text x="48" y="198" font-size="11" fill="#92400e">Besin monomerlerinden ATP sentezlenir (Fosforilasyon)</text>\n  <text x="48" y="215" font-size="11" fill="#92400e">ve yaşamsal olaylarda harcanır (Defosforilasyon).</text>\n  <rect x="355" y="42" width="320" height="202" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">METABOLİZMA = ANABOLİZMA + KATABOLİZMA</text>\n  <rect x="372" y="78" width="286" height="62" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="382" y="98" font-size="12" font-weight="bold" fill="#7e22ce">Anabolizma (Özümleme / Yapım):</text>\n  <text x="382" y="116" font-size="11" fill="#581c87">Küçük moleküllerden büyük molekül sentezi.</text>\n  <text x="382" y="131" font-size="11" fill="#581c87">Örnek: Fotosentez, protein ve glikojen sentezi.</text>\n  <rect x="372" y="148" width="286" height="62" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="382" y="168" font-size="12" font-weight="bold" fill="#be123c">Katabolizma (Yadımlama / Yıkım):</text>\n  <text x="382" y="186" font-size="11" fill="#881337">Büyük moleküllerin daha küçük birimlere yıkımı.</text>\n  <text x="382" y="201" font-size="11" fill="#881337">Örnek: Hücresel solunum ve sindirim (hidroliz).</text>\n  <text x="515" y="230" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Gençlikte: Anabolizma &gt; Katabolizma | Yetişkinde: A ≈ K</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HOMEOSTAZİ, BOŞALTIM, UYARILARA TEPKİ VE ADAPTASYON</text>\n  <rect x="25" y="42" width="205" height="200" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="127" y="65" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9f1239">HOMEOSTAZİ &amp; BOŞALTIM</text>\n  <text x="36" y="90" font-size="11" fill="#881337">• İç Dengenin Korunması:</text>\n  <text x="42" y="106" font-size="10.5" fill="#9f1239">Vücut sıcaklığı, su ve pH dengesi.</text>\n  <text x="36" y="130" font-size="11" fill="#881337">• Boşaltım:</text>\n  <text x="42" y="146" font-size="10.5" fill="#9f1239">Metabolik atıkların (CO₂, NH₃,</text>\n  <text x="42" y="162" font-size="10.5" fill="#9f1239">üre, fazla su) uzaklaştırılması.</text>\n  <text x="42" y="182" font-size="10.5" fill="#9f1239">Tek hücrelide: Hücre zarı /</text>\n  <text x="42" y="198" font-size="10.5" fill="#9f1239">kontraktil koful.</text>\n  <text x="42" y="214" font-size="10.5" fill="#9f1239">Bitkide: Terleme, damlama,</text>\n  <text x="42" y="230" font-size="10.5" fill="#9f1239">yaprak dökümü.</text>\n  <rect x="247" y="42" width="205" height="200" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="350" y="65" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">TEPKİ, BÜYÜME &amp; ÜREME</text>\n  <text x="258" y="90" font-size="11" fill="#164e63">• Uyarılara Tepki &amp; Hareket:</text>\n  <text x="264" y="106" font-size="10.5" fill="#155e75">Öglenanın ışığa yönelmesi (aktif),</text>\n  <text x="264" y="122" font-size="10.5" fill="#155e75">ayçiçeğinin yönelimi (pasif).</text>\n  <text x="258" y="146" font-size="11" fill="#164e63">• Büyüme ve Gelişme:</text>\n  <text x="264" y="162" font-size="10.5" fill="#155e75">Tek hücrelide sitoplazma hacmi</text>\n  <text x="264" y="178" font-size="10.5" fill="#155e75">artışı; çok hücrelide hücre sayısı</text>\n  <text x="264" y="194" font-size="10.5" fill="#155e75">ve hacmi artışı.</text>\n  <text x="258" y="216" font-size="11" fill="#164e63">• Üreme: Neslin devamı için</text>\n  <text x="264" y="232" font-size="10.5" fill="#155e75">gerekli, bireyin yaşamı için şart değil.</text>\n  <rect x="470" y="42" width="205" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="572" y="65" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">VARYASYON &amp; ADAPTASYON</text>\n  <text x="481" y="90" font-size="11" fill="#14532d">• Varyasyon (Çeşitlilik):</text>\n  <text x="487" y="106" font-size="10.5" fill="#166534">Aynı türün bireyleri arasındaki</text>\n  <text x="487" y="122" font-size="10.5" fill="#166534">kalıtsal farklılıklar (göz rengi vb.).</text>\n  <text x="481" y="148" font-size="11" fill="#14532d">• Adaptasyon (Uyum):</text>\n  <text x="487" y="164" font-size="10.5" fill="#166534">Canlının yaşama ve üreme şansını</text>\n  <text x="487" y="180" font-size="10.5" fill="#166534">artıran kalıtsal özellikler.</text>\n  <text x="487" y="200" font-size="10.5" fill="#166534">Örnek: Kaktüsün diken yapraklı</text>\n  <text x="487" y="216" font-size="10.5" fill="#166534">olması, kutup ayısının post rengi.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
